import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import axios from 'axios';
import './pages.css';

const Home = () => {
    const [complaint, setComplaint] = useState('');
    const dispatch = useDispatch();

    // Redux state
    const complaints = useSelector(state => state.complaints.complaints);

    // ✅ API base URL (change later if needed)
    const API_URL = 'http://localhost:5000/complaints';

    // ✅ Fetch complaints from API on page load
    useEffect(() => {
        axios.get(API_URL)
            .then(response => {
                // assuming API returns array of complaints
                dispatch({
                    type: 'SET_COMPLAINTS',
                    payload: response.data
                });
            })
            .catch(error => {
                console.error('Error fetching complaints:', error);
            });
    }, [dispatch]);

    // ✅ Add complaint (Redux + API)
    const handleAdd = () => {
        if (complaint.trim() !== '') {
            axios.post(API_URL, { text: complaint })
                .then(response => {
                    dispatch({
                        type: 'ADD_COMPLAINT',
                        payload: response.data.text || complaint
                    });
                    setComplaint('');
                })
                .catch(error => {
                    console.error('Error submitting complaint:', error);
                });
        }
    };

    return (
        <div className="page-container">
            <h2>Home</h2>

            <div className="complaint-section">
                <textarea
                    placeholder="Enter your complaint"
                    value={complaint}
                    onChange={(e) => setComplaint(e.target.value)}
                />
                <button onClick={handleAdd}>Submit Complaint</button>
            </div>

            <div className="complaint-list">
                <h3>Complaints</h3>
                <ul>
                    {complaints.map((c, i) => (
                        <li key={i}>{c}</li>
                    ))}
                </ul>
            </div>
        </div>
    );
};

export default Home;
